class Solution {
    public int brightestPosition(int[][] lights) {
        TreeMap<Integer, Integer> diff = new TreeMap<>();
        for (int[] l : lights) {
            diff.merge(l[0] - l[1], 1, Integer::sum);
            diff.merge(l[0] + l[1] + 1, -1, Integer::sum);
        }
        int cur = 0, best = 0, ans = 0;
        for (Map.Entry<Integer, Integer> e : diff.entrySet()) {
            cur += e.getValue();
            if (cur > best) {
                best = cur;
                ans = e.getKey();
            }
        }
        return ans;
    }
}
